#nullable enable // autogenerated

using System.Threading.Tasks;
using Cysharp.Threading.Tasks;
using MVZ2.Managers;

namespace MVZ2.ResourcePacks
{
    public abstract class ResourcePackReference
    {
        public virtual bool IsBuiltin => false;
        public abstract UniTask<ResourcePackMetadata?> LoadMetadata(MainManager main);
        public abstract UniTask<ResourcePack?> LoadPack(MainManager main, int dataVersion);
        public abstract UniTask<bool> Export(MainManager main, string destPath);
        public abstract bool Delete();
        public abstract string GetKey();
        public abstract string GetFileName();
        public override string ToString()
        {
            return GetKey();
        }
    }
}
